<script setup>
// Code Generated by AI: AI helped wire filter and sort actions to emitted events.
defineProps({ activeFilter: { type: String, required: true } });
const emit = defineEmits(["filter", "sort"]);
// Send the selected value to App, where the sort state actually lives.
function onSortChange(event) { emit("sort", event.target.value); }
</script>

<template>
  <div class="controls">
    <div class="filters" role="group" aria-label="Filter animals">
      <button type="button" :class="{ active: activeFilter === 'all' }" @click="emit('filter', 'all')">All</button>
      <button type="button" :class="{ active: activeFilter === 'available' }" @click="emit('filter', 'available')">Available</button>
      <button type="button" :class="{ active: activeFilter === 'adopted' }" @click="emit('filter', 'adopted')">Adopted</button>
    </div>
    <label for="sort-animals">Sort by:</label>
    <select id="sort-animals" @change="onSortChange">
      <option value="default">Original order</option>
      <option value="name">Name</option>
      <option value="age">Age</option>
    </select>
  </div>
</template>
